      author: MessageAuthorIdentity.fromJson(
        _readRequired(object, 'author', typeName),
      ),
      sequence: MessageSequence.fromJson(
        _readRequired(object, 'sequence', typeName),
      ),
      createdAt: IsoTimestamp.fromJson(
        _readRequired(object, 'createdAt', typeName),
      ),
      updatedAt: IsoTimestamp.fromJson(
        _readRequired(object, 'updatedAt', typeName),
      ),
      revision: MessageRevisionMetadata.fromJson(
        _readRequired(object, 'revision', typeName),
      ),
      replyTo: object.containsKey('replyTo')
          ? MessageReplyReference.fromJson(object['replyTo'])
          : null,
      threadSummary: object.containsKey('threadSummary')
          ? ThreadSummary.fromJson(object['threadSummary'])
          : null,
    );

Map<String, Object?> _readObject(Object? json, String typeName) {
  if (json is! Map<Object?, Object?>) {
    throw FormatException('$typeName must be a JSON object.');
  }
  final object = <String, Object?>{};
  for (final entry in json.entries) {
    final key = entry.key;
    if (key is! String) {
      throw FormatException('$typeName keys must be strings.');
    }
    object[key] = entry.value;
  }
  return object;
}

void _ensureAllowedFields(
  Map<String, Object?> object,
  Set<String> allowed,
  String typeName,
) {
  for (final field in object.keys) {
    if (!allowed.contains(field)) {
      throw FormatException('$typeName.$field is not allowed.');
    }
  }
}

Object? _readRequired(
  Map<String, Object?> object,
  String field,
  String typeName,
) {
  if (!object.containsKey(field)) {
    throw FormatException('$typeName.$field is required.');
  }
  return object[field];
}

MessageId _readReplyMessageId(Object? json) {
  final id = MessageId.fromJson(json);
  final value = id.value;
  if (value.isEmpty ||
      value.trim() != value ||
      RegExp(r'[\x00-\x1f\x7f-\x9f\u2028\u2029]').hasMatch(value) ||
      utf8.encode(value).length > 255) {
    throw const FormatException('MessageReplyReference.messageId must be a safe identifier of at most 255 UTF-8 bytes.');
  }
  return id;
}

bool _readBool(Object? json, String fieldName) {
  if (json is! bool) {
    throw FormatException('$fieldName must be a boolean JSON value.');
  }
  return json;
}

String _readString(Object? json, String fieldName) {
  if (json is! String) {
    throw FormatException('$fieldName must be a string JSON value.');
  }
  return json;
}

int _readInt(Object? json, String fieldName, {required int minimum}) {
  if (json is! int || json < minimum) {
    throw FormatException(
      '$fieldName must be an integer greater than or equal to $minimum.',
    );
  }
  return json;
}

int? _readNullableInt(Object? json, String fieldName, {required int minimum}) =>
    json == null ? null : _readInt(json, fieldName, minimum: minimum);

List<Object?> _readList(Object? json, String fieldName) {
  if (json is! List<Object?>) {
    throw FormatException('$fieldName must be a JSON array.');
  }
  return json;
}

Object? _freezeJson(Object? value, String fieldName) {
  if (value == null || value is String || value is bool || value is int) {
    return value;
  }
  if (value is double) {
    if (!value.isFinite) {
      throw FormatException('$fieldName must contain valid JSON values.');
    }
    return value;
  }
  if (value is List<Object?>) {
    return UnmodifiableListView<Object?>(
      value.map((item) => _freezeJson(item, fieldName)).toList(),
    );
  }
  if (value is Map<Object?, Object?>) {
    final copy = <String, Object?>{};
    for (final entry in value.entries) {
      if (entry.key is! String) {
        throw FormatException('$fieldName object keys must be strings.');
      }
      copy[entry.key as String] = _freezeJson(entry.value, fieldName);
    }
    return UnmodifiableMapView<String, Object?>(copy);
  }
  throw FormatException('$fieldName must contain only valid JSON values.');
}

Object? _copyJson(Object? value) {
  if (value is List<Object?>) {
    return value.map(_copyJson).toList();
  }
  if (value is Map<Object?, Object?>) {
    return <String, Object?>{
      for (final entry in value.entries)
        entry.key as String: _copyJson(entry.value),
    };
  }
  return value;
}
